1	package water
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10		"time"
11	)
12	
13	// 本文件保护“打开本地数据”时的记录完整性校验：
14	// 每份样品的原测量中同一个项目名只能出现一次，这条规则对任何状态的样品都生效，
15	// 包括没有逐项判定的待判定样品，以及待判定后直接作废、没有历史判定依据的样品；
16	// 重复按保存的完整项目名判断，不靠相邻、不因同值（含两个零）放行。
17	// 带结论的样品还要求原测量项目与逐项判定按项目名完整一一对应、且对应项目的
18	// 测量值一致；缺项、多项、判定项目重复、测量值对不上（零也是合法测量值）或
19	// 整份样品没有测量项目，都必须让整次 Open 失败，返回 nil 存放，错误信息点到
20	// 具体样品编号与项目，且不覆盖原文件、不静默跳过、不择一保留或合并重复测量、
21	// 不补判定、不改成待判定。超标标记还必须与这份样品已保存的判定依据一致：
22	// 每条判定测量值严格大于其保存的上限才应为超标，小于或等于（含等于、零或负数
23	// 组合）都应为达标；整份标记必须与逐项结论一致，任一超标即为真、全部达标即为
24	// 假。单项标记相反，或单项都对而整份标记相反，都让整次 Open 失败；不修正标记、
25	// 不按当前限值重做判定。待判定样品、待判定后作废（无历史依据）的样品在原测量
26	// 不重复时不受影响；已确认后作废但历史依据完整且标记一致的样品继续兼容。
27	
28	const (
29		openPH   = "pH"
30		openTurb = "浊度"
31	)
32	
33	func openEff() time.Time { return at(1, 0) }
34	
35	// writeDiskFile 手工写入一份数据文件，便于构造正常流程不会产生的损坏记录。
36	func writeDiskFile(t *testing.T, dir string, st diskState) {
37		t.Helper()
38		data, err := json.MarshalIndent(st, "", "  ")
39		if err != nil {
40			t.Fatalf("marshal data file: %v", err)
41		}
42		if err := os.WriteFile(filepath.Join(dir, "water-data.json"), data, 0o644); err != nil {
43			t.Fatalf("write data file: %v", err)
44		}
45	}
46	
47	func openPoints() map[string]SamplingPoint {
48		return map[string]SamplingPoint{"P1": {ID: "P1", Name: "一号取水口"}}
49	}
50	
51	// phTurbResults 是与 pH 9、浊度 4 的原测量完整对应的两条判定，
52	// 排列顺序故意与测量相反，用来证明按项目名对应而非按位置对应。
53	func phTurbResults() []ItemResult {
54		return []ItemResult{
55			{Item: openTurb, Value: 4, Limit: 4, LimitEffective: openEff(), Exceeded: false},
56			{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
57		}
58	}
59	
60	func phTurbMeasurements() []Measurement {
61		return []Measurement{
62			{Item: openPH, Value: 9},
63			{Item: openTurb, Value: 4},
64		}
65	}
66	
67	// assertOpenRejects 断言打开整次失败：返回 nil 存放、错误可识别为
68	// ErrCorruptRecord，且信息包含出问题的样品编号与项目（noItem 为 true 时
69	// 只要求编号），原文件字节不被改动。
70	func assertOpenRejects(t *testing.T, dir, sampleID, itemHint string, noItem bool) {
71		t.Helper()
72		before, err := os.ReadFile(filepath.Join(dir, "water-data.json"))
73		if err != nil {
74			t.Fatalf("read file before open: %v", err)
75		}
76		got, err := Open(dir)
77		if err == nil {
78			if got != nil {
79				got.Close()
80			}
81			t.Fatalf("损坏数据必须让整次 Open 失败，sample=%s", sampleID)
82		}
83		if got != nil {
84			t.Fatalf("打开失败时不得返回可用的数据存放对象，got %#v", got)
85		}
86		if !errors.Is(err, ErrCorruptRecord) {
87			t.Fatalf("应返回 ErrCorruptRecord，got %v", err)
88		}
89		msg := err.Error()
90		if !strings.Contains(msg, sampleID) {
91			t.Fatalf("错误信息应指出样品编号 %q，实际 %q", sampleID, msg)
92		}
93		if !noItem && itemHint != "" && !strings.Contains(msg, itemHint) {
94			t.Fatalf("错误信息应指出项目 %q，实际 %q", itemHint, msg)
95		}
96		after, rerr := os.ReadFile(filepath.Join(dir, "water-data.json"))
97		if rerr != nil {
98			t.Fatalf("read file after open: %v", rerr)
99		}
100		if string(after) != string(before) {
101			t.Fatalf("打开失败不得覆盖或改写原数据文件")
102		}
103	}
104	
105	// 已确认样品只剩一个项目的判定依据（浊度缺失）：即使整份超标标记还在，
106	// 也不能凭该标记返回达标或超标，整次打开失败并点名样品与缺失项目。
107	func TestOpenConfirmedMissingItemResult(t *testing.T) {
108		dir := t.TempDir()
109		writeDiskFile(t, dir, diskState{
110			Points: openPoints(),
111			Samples: map[string]*Sample{
112				"S1": {
113					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
114					Measurements: phTurbMeasurements(),
115					Status:       StatusConfirmed, Exceeded: true,
116					Results: []ItemResult{
117						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
118					},
119				},
120			},
121		})
122		assertOpenRejects(t, dir, "S1", openTurb, false)
123	}
124	
125	// 两条判定都在，但浊度判定里的测量值写成了 3（原测量是 4）：
126	// 项目名称相同也不能接受来自另一份记录的测量值，整次打开失败。
127	func TestOpenConfirmedMismatchedValue(t *testing.T) {
128		dir := t.TempDir()
129		results := phTurbResults()
130		results[0].Value = 3 // 浊度 4 被写成 3
131		writeDiskFile(t, dir, diskState{
132			Points: openPoints(),
133			Samples: map[string]*Sample{
134				"S1": {
135					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
136					Measurements: phTurbMeasurements(),
137					Status:       StatusConfirmed, Exceeded: false,
138					Results: results,
139				},
140			},
141		})
142		assertOpenRejects(t, dir, "S1", openTurb, false)
143	}
144	
145	// 零是合法测量值：原测量与判定都是零时必须正常读入；只有判定值被改成
146	// 非零（对不上）时才拒绝，不能把零当成没有填写。
147	func TestOpenConfirmedZeroValueIsValid(t *testing.T) {
148		dir := t.TempDir()
149		zeroResults := []ItemResult{
150			{Item: openTurb, Value: 0, Limit: 4, LimitEffective: openEff(), Exceeded: false},
151			{Item: openPH, Value: 0, Limit: 8, LimitEffective: openEff(), Exceeded: false},
152		}
153	
154		// 完整且为零：成功读入，零值原样保留。
155		writeDiskFile(t, dir, diskState{
156			Points: openPoints(),
157			Samples: map[string]*Sample{
158				"S1": {
159					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
160					Measurements: []Measurement{{Item: openPH, Value: 0}, {Item: openTurb, Value: 0}},
161					Status:       StatusConfirmed, Exceeded: false,
162					Results: zeroResults,
163				},
164			},
165		})
166		s, err := Open(dir)
167		if err != nil {
168			t.Fatalf("零是合法测量值，完整记录应正常读入: %v", err)
169		}
170		list, err := s.ListByPoint("P1")
171		if err != nil || len(list) != 1 {
172			t.Fatalf("ListByPoint: %+v err=%v", list, err)
173		}
174		ms := map[string]float64{}
175		for _, m := range list[0].Measurements {
176			ms[m.Item] = m.Value
177		}
178		if ms[openPH] != 0 || ms[openTurb] != 0 {
179			t.Fatalf("零测量值必须原样保留: %+v", list[0].Measurements)
180		}
181		if err := s.Close(); err != nil {
182			t.Fatalf("Close: %v", err)
183		}
184	
185		// 判定把零改成 1：对不上，整次失败；错误仍点名该项目。
186		bad := []ItemResult{
187			zeroResults[0],
188			{Item: openPH, Value: 1, Limit: 8, LimitEffective: openEff(), Exceeded: false},
189		}
190		writeDiskFile(t, dir, diskState{
191			Points: openPoints(),
192			Samples: map[string]*Sample{
193				"S1": {
194					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
195					Measurements: []Measurement{{Item: openPH, Value: 0}, {Item: openTurb, Value: 0}},
196					Status:       StatusConfirmed, Exceeded: false,
197					Results: bad,
198				},
199			},
200		})
201		assertOpenRejects(t, dir, "S1", openPH, false)
202	}
203	
204	// 同一项目在原测量里出现两次，是记录有误：整次打开失败。
205	func TestOpenConfirmedDuplicateMeasurement(t *testing.T) {
206		dir := t.TempDir()
207		writeDiskFile(t, dir, diskState{
208			Points: openPoints(),
209			Samples: map[string]*Sample{
210				"S1": {
211					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
212					Measurements: []Measurement{
213						{Item: openPH, Value: 9}, {Item: openPH, Value: 7},
214					},
215					Status: StatusConfirmed, Exceeded: true,
216					Results: []ItemResult{
217						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
218					},
219				},
220			},
221		})
222		assertOpenRejects(t, dir, "S1", openPH, false)
223	}
224	
225	// 同一项目在判定中出现两次，同样是记录有误：整次打开失败。
226	func TestOpenConfirmedDuplicateResult(t *testing.T) {
227		dir := t.TempDir()
228		writeDiskFile(t, dir, diskState{
229			Points: openPoints(),
230			Samples: map[string]*Sample{
231				"S1": {
232					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
233					Measurements: []Measurement{{Item: openPH, Value: 9}},
234					Status:       StatusConfirmed, Exceeded: true,
235					Results: []ItemResult{
236						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
237						{Item: openPH, Value: 9, Limit: 6, LimitEffective: openEff(), Exceeded: true},
238					},
239				},
240			},
241		})
242		assertOpenRejects(t, dir, "S1", openPH, false)
243	}
244	
245	// 判定中出现原测量没有的项目：整次打开失败并点名多出的项目。
246	func TestOpenConfirmedExtraResultItem(t *testing.T) {
247		dir := t.TempDir()
248		writeDiskFile(t, dir, diskState{
249			Points: openPoints(),
250			Samples: map[string]*Sample{
251				"S1": {
252					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
253					Measurements: []Measurement{{Item: openPH, Value: 9}},
254					Status:       StatusConfirmed, Exceeded: true,
255					Results: []ItemResult{
256						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
257						{Item: "COD", Value: 1, Limit: 30, LimitEffective: openEff(), Exceeded: false},
258					},
259				},
260			},
261		})
262		assertOpenRejects(t, dir, "S1", "COD", false)
263	}
264	
265	// 已确认样品一个测量项目都没有时也要失败，错误指出是哪份样品。
266	func TestOpenConfirmedNoMeasurements(t *testing.T) {
267		dir := t.TempDir()
268		writeDiskFile(t, dir, diskState{
269			Points: openPoints(),
270			Samples: map[string]*Sample{
271				"S1": {
272					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
273					Status: StatusConfirmed, Exceeded: false,
274					Results: nil,
275				},
276			},
277		})
278		assertOpenRejects(t, dir, "S1", "", true)
279	}
280	
281	// 一个文件里其他样品正常，也不能静默跳过有问题的样品继续打开：
282	// 整次失败、无可用存放，正常样品也读不到。
283	func TestOpenOneBadSampleRejectsWholeFile(t *testing.T) {
284		dir := t.TempDir()
285		writeDiskFile(t, dir, diskState{
286			Points: openPoints(),
287			Samples: map[string]*Sample{
288				// 完整、正常的已确认样品。
289				"S-GOOD": {
290					ID: "S-GOOD", PointID: "P1", SampledAt: at(5, 0),
291					Measurements: []Measurement{{Item: openPH, Value: 7}},
292					Status:       StatusConfirmed, Exceeded: false,
293					Results: []ItemResult{
294						{Item: openPH, Value: 7, Limit: 8, LimitEffective: openEff(), Exceeded: false},
295					},
296				},
297				// 缺浊度判定的损坏样品。
298				"S-BAD": {
299					ID: "S-BAD", PointID: "P1", SampledAt: at(10, 0),
300					Measurements: phTurbMeasurements(),
301					Status:       StatusConfirmed, Exceeded: true,
302					Results: []ItemResult{
303						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
304					},
305				},
306			},
307		})
308		assertOpenRejects(t, dir, "S-BAD", openTurb, false)
309	}
310	
311	// 完整记录按项目名对应：两个列表排列顺序不同不影响读入；读入后测量与判定
312	// 仍各自保留原有顺序，已保存的上限、生效时间、逐项结论与整份超标标记原样保留。
313	func TestOpenCompleteRecordOrderPreserved(t *testing.T) {
314		dir := t.TempDir()
315		wantMeas := phTurbMeasurements() // pH 在前、浊度在后
316		wantResults := phTurbResults()   // 浊度在前、pH 在后（故意相反）
317		writeDiskFile(t, dir, diskState{
318			Points: openPoints(),
319			Samples: map[string]*Sample{
320				"S1": {
321					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
322					Measurements: wantMeas,
323					Status:       StatusConfirmed, Exceeded: true,
324					Results: wantResults,
325				},
326			},
327		})
328		s, err := Open(dir)
329		if err != nil {
330			t.Fatalf("完整记录（顺序相反）应正常读入: %v", err)
331		}
332		defer s.Close()
333	
334		latest, ok, err := s.LatestResult("P1")
335		if err != nil || !ok || latest.ID != "S1" {
336			t.Fatalf("最近有效结果应指向 S1: %+v ok=%v err=%v", latest, ok, err)
337		}
338		// 原测量顺序保留。
339		if len(latest.Measurements) != 2 ||
340			latest.Measurements[0].Item != openPH || latest.Measurements[0].Value != 9 ||
341			latest.Measurements[1].Item != openTurb || latest.Measurements[1].Value != 4 {
342			t.Fatalf("原测量顺序必须保留: %+v", latest.Measurements)
343		}
344		// 判定顺序保留。
345		if len(latest.Results) != 2 ||
346			latest.Results[0].Item != openTurb || latest.Results[0].Value != 4 ||
347			latest.Results[1].Item != openPH || latest.Results[1].Value != 9 {
348			t.Fatalf("逐项判定顺序必须保留: %+v", latest.Results)
349		}
350		// 已保存的上限、生效时间、逐项结论与整份超标标记原样保留，不重新计算。
351		turb := latest.Results[0]
352		if turb.Limit != 4 || !turb.LimitEffective.Equal(openEff()) || turb.Exceeded {
353			t.Fatalf("浊度判定依据应原样保留: %+v", turb)
354		}
355		ph := latest.Results[1]
356		if ph.Limit != 8 || !ph.LimitEffective.Equal(openEff()) || !ph.Exceeded {
357			t.Fatalf("pH 判定依据应原样保留: %+v", ph)
358		}
359		if !latest.Exceeded {
360			t.Fatalf("整份超标标记应原样保留为 true")
361		}
362		// 重复确认返回同一份已保存依据。
363		again, err := s.Confirm("S1")
364		if err != nil {
365			t.Fatalf("重复确认: %v", err)
366		}
367		if len(again.Results) != 2 || again.Results[0].Item != openTurb ||
368			again.Results[1].Item != openPH || !again.Exceeded {
369			t.Fatalf("重复确认应返回原保存依据: %+v", again.Results)
370		}
371	}
372	
373	// 后来新增或补录的限值即使会改变重新判定的结果，也不能据此拒绝完整记录，
374	// 更不能在打开时重算结论：已保存的上限、生效时间与超标结论保持原样。
375	func TestOpenCompleteRecordUnaffectedByNewerLimits(t *testing.T) {
376		s, dir := open(t)
377		mustPoint(t, s, "P1", "一号取水口")
378		mustLimit(t, s, "P1", openPH, 8.0, openEff())
379		mustSample(t, s, "S1", "P1", at(10, 0), Measurement{Item: openPH, Value: 9})
380		conf, err := s.Confirm("S1")
381		if err != nil || !conf.Exceeded || conf.Results[0].Limit != 8.0 {
382			t.Fatalf("setup: 9 > 8 应超标: %+v err=%v", conf, err)
383		}
384		if err := s.Close(); err != nil {
385			t.Fatalf("Close: %v", err)
386		}
387	
388		// 补录一版采样时刻之后才生效、更宽松的限值；再补一版采样之前生效的
389		// 宽松限值（若重算就会变成达标）。
390		s2, err := Open(dir)
391		if err != nil {
392			t.Fatalf("reopen for backfill: %v", err)
393		}
394		mustLimit(t, s2, "P1", openPH, 100.0, at(15, 0))
395		mustLimit(t, s2, "P1", openPH, 100.0, at(2, 0))
396		if err := s2.Close(); err != nil {
397			t.Fatalf("Close s2: %v", err)
398		}
399	
400		// 重新打开：完整记录不被新限值拒绝，结论仍是保存时的 8@09-01、超标。
401		s3, err := Open(dir)
402		if err != nil {
403			t.Fatalf("含新增限值时重新打开完整记录不应失败: %v", err)
404		}
405		defer s3.Close()
