950					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
951					Measurements: []Measurement{{Item: openPH, Value: 9}},
952					// 单项与整份都错成“达标”，单项矛盾必须先报出并点名项目。
953					Status: StatusConfirmed, Exceeded: false,
954					Results: []ItemResult{
955						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: false},
956					},
957				},
958			},
959		})
960		assertOpenRejects(t, dir, "S1", openPH, false)
961	}
962	
963	// 测量值 7、上限 8 的达标判定却保存为超标：反向标错同样拒绝。
964	func TestOpenItemCompliantMarkedExceeded(t *testing.T) {
