1099	// 已确认后作废、逐项依据仍保留的样品，超标标记与依据矛盾时同样拒绝：
1100	// 作废只取消有效资格，不能让错误结论借“历史记录”名义混入台账。
1101	func TestOpenVoidedAfterConfirmedItemFlagContradiction(t *testing.T) {
