54			}
55		}
56		after, rerr := os.ReadFile(filepath.Join(dir, "water-data.json"))
57		if rerr != nil {
58			t.Fatalf("read file after open: %v", rerr)
59		}
60		if string(after) != string(before) {
61			t.Fatalf("打开失败不得覆盖或改写原数据文件")
62		}
63	}
