  },
  "samples": {
    "S1": {
      "id": "S1", "pointId": "P1",
      "sampledAt": "` + at(10, 0).Format(time.RFC3339Nano) + `",
      "measurements": [{"item": "pH", "value": -2}, {"item": "COD", "value": 30}],
      "status": "pending"
    }
  }
}`
	writeRawDiskFile(t, dir, raw)
	s, err := Open(dir)
	if err != nil {
		t.Fatalf("明确保存的负数与正数限值应正常打开: %v", err)
	}
	defer s.Close()
	smp, err := s.Confirm("S1")
	if err != nil {
