	// writeDiskFile 经 Go 结构体序列化，value 字段总会写成 0；改写原始 JSON
	// 把第二条的 value 字段去掉，构造出只有缺少数值版本的数据文件。
	data, err := os.ReadFile(filepath.Join(dir, "water-data.json"))
	if err != nil {
		t.Fatalf("read data file: %v", err)
	}
	raw := strings.Replace(string(data),
		`"pointId": "`+zeroPoint+`",`+"\n"+`        "item": "B",`+"\n"+`        "value": 0,`,
		`"pointId": "`+zeroPoint+`",`+"\n"+`        "item": "B",`, 1)
	if !strings.Contains(raw, `"item": "B",`) || strings.Contains(raw, `"item": "B",`+"\n"+`        "value"`) {
		t.Fatalf("构造缺少数值的限值记录失败: %s", raw)
	}
	writeRawDiskFile(t, dir, raw)
	assertOpenRejectsLimitValue(t, dir, zeroPoint, "B", openEff())
}

